// Берем данные из профиля пользователя (результат работы Google Sheets)
const sheetData = $('User Profile').first().json;

// Берем исходное сообщение из Telegram
const telegramData = $('Registrar').first().json;

// ВАЖНО: Забираем текст напрямую из ноды Merge, 
// так как нода User Profile затерла стандартный поток
const mergeData = $('Merge Экстракторы').first().json || {};
const extractedText = mergeData.text || ""; 

// Берем картинку (если она есть) из стартового узла
const binaryData = $('Registrar').first().binary;

return [{
  json: {
    // Передаем только самое необходимое для авторизации
    medical_record: {
      User_ID: sheetData.User_ID, 
      Location: sheetData.Location
    },
    user_message: telegramData.message?.text || telegramData.message?.caption || "Данные во вложении",

    // Кладем найденный 'text' в переменную 'extracted_text', которую ждет промпт
    extracted_text: extractedText, 

    telegram_id: telegramData.message?.from?.id,
    chat_id: telegramData.message?.chat?.id
  },
  binary: binaryData 
}];

// 1. Получаем даты, которые УЖЕ ЕСТЬ в Daily_Trends (приходят на вход из узла чтения)
const existingDates = items.map(item => item.json['Дата']).filter(Boolean);

// 2. Получаем сырой CSV (обращаемся к предыдущему узлу по имени)
const csvRecords = $('Extract Welltory').all().map(item => item.json);

const dailyWelltory = {};

csvRecords.forEach(row => {
  const fullDate = String(row['Date'] || '').trim();
  const dateOnly = fullDate.split('T')[0];

  if (!dateOnly) return;

  // 🛡 ГЛАВНЫЙ ФИЛЬТР: Берем данные ТОЛЬКО если эта дата уже есть в базе!
  if (existingDates.includes(dateOnly)) {
    // Берем только первый (утренний) замер
    if (!dailyWelltory[dateOnly]) {
      dailyWelltory[dateOnly] = {
        "Дата": dateOnly, 
        "ВСР_Стресс": Number(row['Stress(HRV)'] || 0),
        "ВСР_Энергия": Number(row['Energy(HRV)'] || 0),
        "ВСР_RMSSD": Number(row['rMSSD'] || 0),
        "ВСР_SDNN": Number(row['SDNN'] || 0)
      };
    }
  }
});

// Отдаем чистые данные без всяких сообщений для Telegram
return Object.values(dailyWelltory).map(data => ({ json: data }));

// 1. Получаем даты, которые УЖЕ ЕСТЬ в базе
const existingDates = items.map(item => item.json['Дата']).filter(Boolean);

// 2. ЧИТАЕМ ДАННЫЕ
let rawText = "";
const switchNode = $('Сортировка документов').first();

if (switchNode.binary && switchNode.binary.data) {
  rawText = Buffer.from(switchNode.binary.data.data, 'base64').toString('utf8');
}
if (!rawText || rawText.length < 20) {
  rawText = switchNode.json.userText || switchNode.json.message?.text || "";
}

const lines = rawText.split('\n');
const dailyPrana = {};

// 3. Сканируем каждую строчку
lines.forEach(line => {
  const columns = line.split(',');

  // Ищем дату
  const dateColIndex = columns.findIndex(col => /\d{4}-\d{2}-\d{2}/.test(col));
  if (dateColIndex === -1) return; 

  const dateVal = columns[dateColIndex].match(/\d{4}-\d{2}-\d{2}/)[0];
  if (!existingDates.includes(dateVal)) return;

  // В Prana ТИП тренировки лежит через 2 колонки после даты, а ДЛИТЕЛЬНОСТЬ - через 3
  const typeRaw = columns[dateColIndex + 2] || '';
  const durationRaw = columns[dateColIndex + 3] || '';

  // Очищаем тип тренировки от любых скрытых символов (оставляем только буквы, цифры, пробелы и дефисы)
  const typeClean = typeRaw.replace(/[^\wА-Яа-яЁё\s\-]/gi, '').trim();

  // Очищаем и считаем длительность
  const durationClean = durationRaw.replace(/[^\dчмсhms]/gi, '');
  let totalMinutes = 0;

  const hMatch = durationClean.match(/(\d+)[чh]/i);
  const mMatch = durationClean.match(/(\d+)[мm]/i);
  const sMatch = durationClean.match(/(\d+)[сs]/i);

  if (hMatch) totalMinutes += parseInt(hMatch[1], 10) * 60;
  if (mMatch) totalMinutes += parseInt(mMatch[1], 10);
  if (sMatch) totalMinutes += parseInt(sMatch[1], 10) / 60;

  if (totalMinutes === 0) return;

  // Создаем запись
  if (!dailyPrana[dateVal]) {
    dailyPrana[dateVal] = {
      "Дата": dateVal,
      "Prana_Длительность_мин": 0,
      "Prana_Тип":[] // Создаем пустой массив для типов тренировок
    };
  }

  // Прибавляем время
  dailyPrana[dateVal]["Prana_Длительность_мин"] += totalMinutes;

  // Добавляем тип тренировки (только если такого еще не было за сегодня)
  if (typeClean && !dailyPrana[dateVal]["Prana_Тип"].includes(typeClean)) {
    dailyPrana[dateVal]["Prana_Тип"].push(typeClean);
  }
});

// Формируем красивый результат перед отправкой
Object.keys(dailyPrana).forEach(date => {
  // Округляем минуты до 1 знака
  dailyPrana[date]["Prana_Длительность_мин"] = Math.round(dailyPrana[date]["Prana_Длительность_мин"] * 10) / 10;

  // Превращаем массив типов в красивую строку через запятую (например: "Расслабление, Дыхание 4-7-8")
  dailyPrana[date]["Prana_Тип"] = dailyPrana[date]["Prana_Тип"].join(', ');
});

// Возвращаем чистые данные для базы
return Object.values(dailyPrana).map(data => ({ json: data }));

